let BaselineWindow = 1d;
let FlagWindow = 1d;
let ThresholdFactor = 1.5; // Exceeds baseline by >50% (factor of 1.5)

// Calculate the average SMB connection count per source/port pair over the last day for each IP:Port combination in the flag window
BaselineData = im_Smb 
| where TimeGenerated >= ago(FlagWindow) and DstIpAddr != '0.0.0.0' // Exclude invalid IPs if any, ensure private range check via context or explicit filter if needed (Sentinel usually handles this with known ranges)
| summarize AvgCount=avg(DstBytes + SrcBytes), TotalPackets=sum(NetworkPackets) by DstIpAddr, bin(TimeGenerated, 1m) 
// Note: The prompt asks for "per private-IP source/port pair". In ASIM network sessions, the destination IP is often the target. However, if we are looking at connections *from* a specific source to SMB ports (445/139), usually DstIpAddr represents the server and SrcIpAddr the client. 
// Re-interpreting "source/port pair" as the unique identifier of the connection endpoint initiating or receiving on those ports. Given ASIM schema, let's assume we are tracking connections *to* SMB services (DstPort 445/139) from various sources, OR connections initiated by a source to an internal target. 
// The prompt says "private-IP source/port pair". This likely means the Source IP and Port combination that is initiating these high-volume sessions.
let BaselineQuery = im_Smb 
| where DstPortNumber in (139, 445) // Filter for SMB ports
| where TimeGenerated >= ago(BaselineWindow)
| summarize AvgCount=avg(DstBytes + SrcBytes), TotalPackets=sum(NetworkPackets) by SrcIpAddr, bin(TimeGenerated, 1m) 
// We need to aggregate the baseline first. But since we don't know which IPs are private without a specific list in KQL easily (unless using `startswith` or known ranges like 10.x.x.x), let's assume standard internal IP filtering logic applies or just calculate on all and filter later if needed. 
// Actually, to get the baseline average *per source/port pair*, we group by SrcIpAddr + Port? No, usually it's per Source IP because ports are fixed for SMB (139/445). The prompt says "source/port pair", implying unique combinations of SrcIP and SrcPort.
let BaselineGrouped = im_Smb 
| where DstPortNumber in (139, 445)
| where TimeGenerated >= ago(BaselineWindow)
| summarize AvgCount=avg(DstBytes + SrcBytes), TotalPackets=sum(NetworkPackets) by SrcIpAddr, bin(TimeGenerated, 1m);

// Now calculate the current window stats and join with baseline to find anomalies.
CurrentData = im_Smb 
| where DstPortNumber in (139, 445)
| where TimeGenerated >= ago(FlagWindow)
| summarize Count=count(), AvgCount=avg(DstBytes + SrcBytes), TotalPackets=sum(NetworkPackets) by SrcIpAddr, bin(TimeGenerated, 1m);

// Join current with baseline to compare. 
// We need the average count over the last day (BaselineWindow). The previous step calculated avg per minute bucket? No, let's simplify:
// Baseline = Average connections per source IP in the last 24 hours.
let BaselineAvg = im_Smb 
| where DstPortNumber in (139, 445) and TimeGenerated >= ago(1d)
| summarize AvgCount=avg(DstBytes + SrcBytes), TotalPackets=sum(NetworkPackets) by SrcIpAddr;

// Current window stats: Average connections per source IP in the last day.
let CurrentStats = im_Smb 
| where DstPortNumber in (139, 445) and TimeGenerated >= ago(1d)
| summarize Count=count(), AvgCount=avg(DstBytes + SrcBytes), TotalPackets=sum(NetworkPackets) by SrcIpAddr;

// Join to find those exceeding baseline * 1.5
CurrentStats 
| join kind=inner (BaselineAvg) on SrcIpAddr 
| where CurrentStats.AvgCount > BaselineAvg.AvgCount * ThresholdFactor

