| let AppPorts = make_set(DstAppName, DstPortNumber);
| extend StandardApps = totable(StandardPorts) | project-to table(AppName=Key, Port=Value), NonStandardApps = make_set(AssociatedNonStandardAppId, AssociatedNonStandardPortNum) where Key != Value;
| summarize count() by SrcIpAddr, DstAppName, bin(TimeGenerated, 5m)
| where AppPorts contains (make_set(80,443)) == false and NonStandardApps is not empty
| order by TimeGenerated desc

